/**
 * Set the day (keeping the current time) to the start of the week + the number of days passed as the first
 * parameter. First day of week is driven by the locale unless explicitly set with the second parameter.
 *
 * @param int              $numberOfDays number of days to add after the start of the current week
 * @param WeekDay|int|null $weekStartsAt optional start allow you to specify the day of week to use to start the week,
 *                                       if not provided, start of week is inferred from the locale
 *                                       (Sunday for en_US, Monday for de_DE, etc.)
 */
public function setDaysFromStartOfWeek(int $numberOfDays, WeekDay|int|null $weekStartsAt = null): static
{
    return $this->addDays($numberOfDays - $this->getDaysFromStartOfWeek(WeekDay::int($weekStartsAt)));
}

/**
 * Set any unit to a new value without overflowing current other unit given.
 *
 * @param string $valueUnit    unit name to modify
 * @param int    $value        new value for the input unit
 * @param string $overflowUnit unit name to not overflow
 */
public function setUnitNoOverflow(string $valueUnit, int $value, string $overflowUnit): static
{
    try {
        $valueUnitName = static::singularUnit(Unit::toName($valueUnit));
        $overflowUnitName = static::singularUnit(Unit::toName($overflowUnit));
        $timezone = $this->getTimezone();
        $year = (int) $this->year;
        $month = (int) $this->month;
        $day = (int) $this->day;
        $hour = (int) $this->hour;
        $minute = (int) $this->minute;
        $second = (int) $this->second;
        $micro = (int) $this->micro;
        $daysInMonth = (int) $this->daysInMonth;
        $lastHour = static::HOURS_PER_DAY - 1;
        $lastMinute = static::MINUTES_PER_HOUR - 1;
        $lastSecond = static::SECONDS_PER_MINUTE - 1;
        $lastMicro = static::MICROSECONDS_PER_SECOND - 1;

        if ($this instanceof DateTimeImmutable) {
            $boundary = $this;
        } else {
            $boundary = clone $this;
        }

        if ($overflowUnitName === 'month') {
            $start = $boundary
                ->setDate($year, $month, 1)
                ->setTime(0, 0, 0, 0)
                ->setTimezone($timezone);
            $end = $this->avoidMutation()
                ->setDate($year, $month, $daysInMonth)
                ->setTime($lastHour, $lastMinute, $lastSecond, $lastMicro)
                ->setTimezone($timezone);

            if ($valueUnitName === 'day') {
                $date = $this->setDate($year, $month, $value);

                if ($date->lessThan($start)) {
                    return $date->mutateIfMutable($start);
                }

                if ($date->greaterThan($end)) {
                    return $date->mutateIfMutable($end);
                }

                return $date;
            }
        } elseif ($overflowUnitName === 'year') {
            $start = $boundary
                ->setDate($year, 1, 1)
                ->setTime(0, 0, 0, 0)
                ->setTimezone($timezone);
            $end = $this->avoidMutation()
                ->setDate($year, static::MONTHS_PER_YEAR, 31)
                ->setTime($lastHour, $lastMinute, $lastSecond, $lastMicro)
                ->setTimezone($timezone);
        } elseif ($overflowUnitName === 'day') {
            $start = $boundary
                ->setTime(0, 0, 0, 0)
                ->setTimezone($timezone);
            $end = $this->avoidMutation()
                ->setTime($lastHour, $lastMinute, $lastSecond, $lastMicro)
                ->setTimezone($timezone);
        } elseif ($overflowUnitName === 'hour') {
            $start = $boundary->startOfHour()->setTimezone($timezone);
            $end = $this->avoidMutation()->endOfHour()->setTimezone($timezone);
        } elseif ($overflowUnitName === 'quarter') {
            $start = $boundary->startOfQuarter()->setTimezone($timezone);
            $end = $this->avoidMutation()->endOfQuarter()->setTimezone($timezone);
        } else {
            $start = $this->avoidMutation()->startOf($overflowUnit);
            $end = $this->avoidMutation()->endOf($overflowUnit);
        }

        if (\in_array($valueUnitName, ['year', 'month', 'day'], true)) {
            $nextYear = $year;
            $nextMonth = $month;
            $nextDay = $day;

            if ($valueUnitName === 'year') {
                $nextYear = $value;
            } elseif ($valueUnitName === 'month') {
                $nextMonth = $value;
            } else {
                $nextDay = $value;
            }

            $date = $this->setDate($nextYear, $nextMonth, $nextDay);
        } elseif (\in_array($valueUnitName, ['hour', 'minute', 'second'], true)) {
            $nextHour = $hour;
            $nextMinute = $minute;
            $nextSecond = $second;

            if ($valueUnitName === 'hour') {
                $nextHour = $value;
            } elseif ($valueUnitName === 'minute') {
                $nextMinute = $value;
            } else {
                $nextSecond = $value;
            }

            $date = $this->setTime($nextHour, $nextMinute, $nextSecond, $micro);
        } else {
            $date = $this->$valueUnit($value);
        }

        if ($date->lessThan($start)) {
            return $date->mutateIfMutable($start);
        }

        if ($date->greaterThan($end)) {
            return $date->mutateIfMutable($end);
        }

        return $date;
    } catch (BadMethodCallException | ReflectionException $exception) {
        throw new UnknownUnitException($valueUnit, 0, $exception);
    }
}

/**
 * Add any unit to a new value without overflowing current other unit given.
 *
 * @param string $valueUnit    unit name to modify
 * @param int    $value        amount to add to the input unit
 * @param string $overflowUnit unit name to not overflow
 */
public function addUnitNoOverflow(string $valueUnit, int $value, string $overflowUnit): static
{
    return $this->setUnitNoOverflow($valueUnit, $this->$valueUnit + $value, $overflowUnit);
}

/**
 * Subtract any unit to a new value without overflowing current other unit given.
 *
 * @param string $valueUnit    unit name to modify
 * @param int    $value        amount to subtract to the input unit
 * @param string $overflowUnit unit name to not overflow
 */
public function subUnitNoOverflow(string $valueUnit, int $value, string $overflowUnit): static
{
    return $this->setUnitNoOverflow($valueUnit, $this->$valueUnit - $value, $overflowUnit);
}

